import React,{useEffect,useState} from 'react';
import {ActivityIndicator,Alert,Image,Linking,Modal,Platform,Pressable,Share,StyleSheet,Text,View,useWindowDimensions} from '@/platform/react-native';
import {Ionicons} from '@/platform/icons';
import {useVideoPlayer,VideoView} from '@/platform/video';
import {WebView} from '@/platform/web-view';
import {Muted,useAppTheme} from './UI';

export type Attachment={url:string;title?:string;mimeType?:string;posterName?:string;posterImage?:string;caption?:string;reactionCount?:number;commentCount?:number;shareCount?:number;liked?:boolean;saved?:boolean;onLike?:()=>void;onComment?:()=>void;onShare?:()=>void;onSave?:()=>void}|null;
function extension(url:string){try{return new URL(url).pathname.split('.').pop()?.toLowerCase()||''}catch{return url.split('?')[0].split('.').pop()?.toLowerCase()||''}}
function isImage(file:NonNullable<Attachment>){return file.mimeType?.startsWith('image/')||['jpg','jpeg','png','gif','webp','bmp','svg'].includes(extension(file.url))}
function isVideo(file:NonNullable<Attachment>){return file.mimeType?.startsWith('video/')||['mp4','webm','mov'].includes(extension(file.url))}
function isPdf(file:NonNullable<Attachment>){return file.mimeType==='application/pdf'||extension(file.url)==='pdf'}
function isOfficeDocument(file:NonNullable<Attachment>){return ['doc','docx','xls','xlsx','ppt','pptx'].includes(extension(file.url))||['application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.ms-excel','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','application/vnd.ms-powerpoint','application/vnd.openxmlformats-officedocument.presentationml.presentation'].includes(file.mimeType||'')}

export function AttachmentPreview({attachment,onClose,overlay}:{attachment:Attachment;onClose:()=>void;overlay?:React.ReactNode}){
 const{palette}=useAppTheme();const{width,height}=useWindowDimensions();
 const[resolved,setResolved]=useState<{url:string;mimeType?:string}|null>(null),[resolving,setResolving]=useState(false),[resolveFailed,setResolveFailed]=useState(false);
 useEffect(()=>{if(!attachment||Platform.OS!=='web'){setResolved(null);setResolving(false);setResolveFailed(false);return}const controller=new AbortController();let objectUrl:string|undefined;setResolving(true);setResolveFailed(false);void fetch(attachment.url,{signal:controller.signal}).then(response=>{if(!response.ok)throw new Error(`Unable to load attachment (${response.status})`);return response.blob()}).then(blob=>{objectUrl=URL.createObjectURL(blob);setResolved({url:objectUrl,mimeType:blob.type||attachment.mimeType})}).catch(error=>{if(error?.name!=='AbortError')setResolveFailed(true)}).finally(()=>setResolving(false));return()=>{controller.abort();if(objectUrl)URL.revokeObjectURL(objectUrl)}},[attachment?.url,attachment?.mimeType]);
 if(!attachment)return null;
 const title=attachment.title||decodeURIComponent(attachment.url.split('/').pop()?.split('?')[0]||'Attachment'),displayAttachment={...attachment,url:resolved?.url||attachment.url,mimeType:resolved?.mimeType||attachment.mimeType},pdf=isPdf(attachment)||isPdf(displayAttachment),office=isOfficeDocument(attachment)||isOfficeDocument(displayAttachment);
 if(isImage(displayAttachment)||isVideo(displayAttachment))return <MediaViewer attachment={displayAttachment} title={title} video={isVideo(displayAttachment)} onClose={onClose} overlay={overlay}/>;
 const maxWidth=Math.min(Math.max(280,width-28),860),maxHeight=Math.min(Math.max(420,height-50),760);
 const save=()=>saveAttachment(attachment,title);
 const share=()=>shareAttachment(attachment,title);
 const fallback=<View style={styles.fallback}><Ionicons name={resolveFailed?'alert-circle-outline':'document-text-outline'} size={64} color={resolveFailed?palette.danger:palette.primary}/><Text numberOfLines={3} style={[styles.fallbackTitle,{color:palette.text}]}>{title}</Text><Muted style={styles.center}>{resolveFailed?'This file could not be loaded inside the preview. Use Save to open it directly.':'This file format cannot be drawn by the device, but it is available here to save, share or open with a compatible app.'}</Muted><Pressable accessibilityRole="button" accessibilityLabel="Open attachment" onPress={()=>void Linking.openURL(attachment.url)} style={[styles.openButton,{backgroundColor:palette.primary}]}><Ionicons name="open-outline" size={18} color="#fff"/><Text style={styles.openText}>Open file</Text></Pressable></View>;
 const onlineDocumentUrl=`https://docs.google.com/gview?embedded=1&url=${encodeURIComponent(attachment.url)}`;
 const preview=resolving?<View style={styles.fallback}><ActivityIndicator size="large" color={palette.primary}/><Muted>Loading payment evidence…</Muted></View>:Platform.OS==='web'&&pdf?React.createElement('iframe',{src:resolved?.url||attachment.url,title,style:{width:'100%',height:'100%',border:'0',backgroundColor:'#fff'}}):Platform.OS==='web'&&office?React.createElement('iframe',{src:onlineDocumentUrl,title,style:{width:'100%',height:'100%',border:'0',backgroundColor:'#fff'}}):Platform.OS!=='web'&&pdf?<WebView source={{uri:Platform.OS==='ios'?attachment.url:onlineDocumentUrl}} style={styles.webView} originWhitelist={['*']} startInLoadingState renderLoading={()=><View style={styles.webLoading}><ActivityIndicator size="large" color={palette.primary}/></View>} onError={()=>setResolveFailed(true)}/>:Platform.OS!=='web'&&office?<WebView source={{uri:onlineDocumentUrl}} style={styles.webView} originWhitelist={['*']} startInLoadingState renderLoading={()=><View style={styles.webLoading}><ActivityIndicator size="large" color={palette.primary}/></View>} onError={()=>setResolveFailed(true)}/>:fallback;
 return <Modal visible transparent animationType="fade" statusBarTranslucent onRequestClose={onClose}><View style={styles.backdrop}><View accessibilityViewIsModal style={[styles.dialog,{width:maxWidth,height:maxHeight,backgroundColor:palette.surface,borderColor:palette.border}]}><View style={[styles.header,{borderBottomColor:palette.border}]}><Text numberOfLines={1} style={[styles.title,{color:palette.text}]}>{title}</Text><View style={styles.headerActions}><HeaderAction icon="share-social-outline" label="Share attachment" onPress={()=>void share()} color={palette.text}/><HeaderAction icon="download-outline" label="Save attachment" onPress={()=>void save()} color={palette.primary}/><HeaderAction icon="close" label="Close preview" onPress={onClose} color={palette.text}/></View></View><View style={[styles.viewer,{backgroundColor:palette.backgroundSoft}]}>{preview}</View></View></View></Modal>;
}

function MediaViewer({attachment,title,video,onClose,overlay}:{attachment:NonNullable<Attachment>;title:string;video:boolean;onClose:()=>void;overlay?:React.ReactNode}){
 const[menu,setMenu]=useState(false);const isPost=Boolean(attachment.posterName||attachment.posterImage||attachment.caption||attachment.onLike||attachment.onComment||attachment.onShare||attachment.onSave);const{width,height}=useWindowDimensions();
 const share=()=>attachment.onShare?.()||shareAttachment(attachment,title),save=()=>saveAttachment(attachment,title);
 const comment=()=>attachment.onComment?.();
 const actions=<><SocialAction icon={attachment.liked?'thumbs-up':'thumbs-up-outline'} count={attachment.reactionCount} label="Like" onPress={attachment.onLike}/><SocialAction icon="chatbubble-outline" count={attachment.commentCount} label="Comments" onPress={comment}/><SocialAction icon="share-social-outline" count={attachment.shareCount} label="Share" onPress={()=>void share()}/><SocialAction icon={attachment.saved?'bookmark':'bookmark-outline'} label="Save post" onPress={attachment.onSave}/></>;
 return <Modal visible animationType="fade" presentationStyle="fullScreen" statusBarTranslucent onRequestClose={onClose}><View style={media.black}><View style={media.top}><HeaderAction icon="close" label="Close media" onPress={onClose} color="#fff"/><Text numberOfLines={1} style={media.mediaTitle}>{title}</Text><HeaderAction icon="share-social-outline" label="Share media" onPress={()=>void share()} color="#fff"/><HeaderAction icon="ellipsis-horizontal" label="Media options" onPress={()=>setMenu(true)} color="#fff"/></View><View style={media.stage}>{video?<FullscreenVideo uri={attachment.url} title={title}/>:<Image source={{uri:attachment.url}} resizeMode="contain" style={[media.image,{width,height:Math.max(260,height-150)}]} accessibilityLabel={title}/>}</View>{isPost&&video?<View pointerEvents="box-none" style={media.social}>{actions}</View>:null}{isPost?<View style={[media.postInfo,!video&&media.photoPostInfo]}><View style={media.posterRow}>{attachment.posterImage?<Image source={{uri:attachment.posterImage}} style={media.avatar}/>:<View style={media.avatarFallback}><Ionicons name="person" size={18} color="#fff"/></View>}<Text numberOfLines={1} style={media.posterName}>{attachment.posterName||'Community member'}</Text></View>{attachment.caption?<Text numberOfLines={2} style={media.caption}>{attachment.caption}</Text>:null}{video?<Pressable accessibilityRole="button" accessibilityLabel="Add a comment" onPress={comment} style={media.commentBox}><Text style={media.commentText}>Add a comment</Text><Ionicons name="send-outline" size={20} color="#fff"/></Pressable>:<View style={media.photoActions}>{actions}</View>}</View>:null}{menu?<><Pressable accessibilityLabel="Close media options" onPress={()=>setMenu(false)} style={media.menuBackdrop}/><View style={media.sheet}><SheetAction label={video?'Save video':'Save photo'} onPress={()=>{setMenu(false);void save()}}/><SheetAction label="Copy link" onPress={()=>{setMenu(false);void copyLink(attachment.url)}}/><SheetAction label="Share" onPress={()=>{setMenu(false);void share()}}/><SheetAction label="Cancel" onPress={()=>setMenu(false)} separate/></View></>:null}{overlay}</View></Modal>;
}

function SocialAction({icon,count,label,onPress}:{icon:keyof typeof Ionicons.glyphMap;count?:number;label:string;onPress?:()=>void}){return <Pressable accessibilityRole="button" accessibilityLabel={label} disabled={!onPress} onPress={onPress} style={media.socialAction}><Ionicons name={icon} size={29} color="#fff"/><Text style={media.socialCount}>{count??''}</Text></Pressable>}

function FullscreenVideo({uri,title}:{uri:string;title:string}){
 const[playing,setPlaying]=useState(false);const player=useVideoPlayer(uri,p=>{p.loop=false;p.muted=false});
 const toggle=()=>{if(playing)player.pause();else player.play();setPlaying(!playing)};
 const skip=(seconds:number)=>{player.currentTime=Math.max(0,player.currentTime+seconds)};
 return <View style={media.videoStage}><VideoView player={player} style={media.video} nativeControls={false} contentFit="contain" accessibilityLabel={title}/><View style={media.videoControls}><RoundAction icon="play-back-outline" label="Back 10 seconds" onPress={()=>skip(-10)}/><Pressable accessibilityRole="button" accessibilityLabel={playing?'Pause video':'Play video'} onPress={toggle} style={media.play}><Ionicons name={playing?'pause':'play'} size={34} color="#fff"/></Pressable><RoundAction icon="play-forward-outline" label="Forward 10 seconds" onPress={()=>skip(10)}/></View></View>;
}

function HeaderAction({icon,label,onPress,color}:{icon:keyof typeof Ionicons.glyphMap;label:string;onPress:()=>void;color:string}){return <Pressable accessibilityRole="button" accessibilityLabel={label} hitSlop={8} onPress={onPress} style={styles.headerAction}><Ionicons name={icon} size={23} color={color}/></Pressable>}
function RoundAction({icon,label,onPress}:{icon:keyof typeof Ionicons.glyphMap;label:string;onPress:()=>void}){return <Pressable accessibilityRole="button" accessibilityLabel={label} onPress={onPress} style={media.round}><Ionicons name={icon} size={23} color="#fff"/></Pressable>}
function SheetAction({label,onPress,separate=false}:{label:string;onPress:()=>void;separate?:boolean}){return <Pressable accessibilityRole="button" accessibilityLabel={label} onPress={onPress} style={[media.sheetAction,separate&&media.separate]}><Text style={media.sheetText}>{label}</Text></Pressable>}

async function saveAttachment(attachment:NonNullable<Attachment>,title:string){try{if(Platform.OS==='web'&&typeof document!=='undefined'){const link=document.createElement('a');link.href=attachment.url;link.download=title;link.target='_blank';link.rel='noopener';document.body.appendChild(link);link.click();link.remove();return}await Linking.openURL(attachment.url)}catch{Alert.alert('Unable to save file','The media could not be saved. Please try again.')}}
async function shareAttachment(attachment:NonNullable<Attachment>,title:string){try{if(Platform.OS==='web'&&typeof navigator!=='undefined'&&navigator.share){await navigator.share({title,url:attachment.url});return}await Share.share({title,message:attachment.url,url:attachment.url})}catch(error:any){if(error?.name!=='AbortError')Alert.alert('Unable to share','The media could not be shared. Please try again.')}}
async function copyLink(url:string){try{if(typeof navigator!=='undefined'&&navigator.clipboard){await navigator.clipboard.writeText(url);Alert.alert('Copied','Media link copied to clipboard.');return}await Share.share({message:url})}catch{Alert.alert('Unable to copy','The media link could not be copied.')}}

